
public class SwitchStatement {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int mark=75; switch(mark) {
		 
		
		case 90:System.out.println("Grade-A");break; 
		case 75:System.out.println("Grade-B");break;
		case 60:System.out.println("Grade-C");break; default:
			System.out.println("Grade-D");break;
	}

}
}